export function sourceGroupFor(lessonId) { return Y1S1_SOURCE_MAP.byLesson[lessonId] || null; }
export function sourceGroupsForWeek(subject, week) { return (Y1S1_SOURCE_MAP.byWeek[subject]?.[week] || []).map(sourceGroupFor).filter(Boolean); }
export function sourceMetaFor(ref, lessonId = '') { const group = lessonId ? sourceGroupFor(lessonId) : null; return group?.sources.find((source) => source.ref === ref) || Y1S1_SOURCE_MAP.bySource[ref]?.[0] || null; }
export function sourceSetLabel(set) { return set === 'new' ? 'New source' : 'Old source'; }
export function sourceRoleLabel(role) { return ({ 'current-primary': 'primary', 'older-supporting': 'supporting', 'older-fallback': 'fallback', assessment: 'assessment/practice', administration: 'administration', 'student-work': 'student work', 'not-mapped-future': 'future scope', 'needs-review': 'needs review' })[role] || 'source'; }
